  await page.locator('#variationChoice').selectOption('exit');assert.equal(await page.locator('#variationPreview').innerText(),'请问，出口在哪儿？');assert.match(await page.locator('#variationPinyin').innerText(),/chūkǒu/);await page.getByRole('button',{name:'Revelar apoio de pinyin'}).click();assert.equal(await page.locator('#practicePinyin').isVisible(),true);
